const originalText = new WeakMap();
const originalAttributes = new WeakMap();
const localizedText = new WeakMap();
const localizedAttributes = new WeakMap();

function localizeText(value, lang) {
  const trimmed = value.trim();
  if (!trimmed) return value;
  const copy = UI_COPY[trimmed];
  if (copy?.[lang]) return value.replace(trimmed, copy[lang]);
  const prefix = Object.keys(UI_COPY).find(key => (key.endsWith(' ') || key.endsWith('(')) && trimmed.startsWith(key));
  if (prefix && UI_COPY[prefix]?.[lang]) {
    return value.replace(trimmed, UI_COPY[prefix][lang] + trimmed.slice(prefix.length));
  }
  return value;
}

export const translateUiCopy = (value, lang = 'en') => localizeText(value, lang);

function applyUiLocale(root, lang) {
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (!originalText.has(node)) originalText.set(node, node.nodeValue);
    else if (localizedText.has(node) && node.nodeValue !== localizedText.get(node)) originalText.set(node, node.nodeValue);
    const original = originalText.get(node);
    const translated = localizeText(original, lang);
    localizedText.set(node, translated);
    if (node.nodeValue !== translated) node.nodeValue = translated;
  }

  const attributes = ['title', 'aria-label', 'placeholder', 'alt'];
  const elements = root.nodeType === Node.ELEMENT_NODE ? [root, ...root.querySelectorAll('*')] : [...root.querySelectorAll('*')];
  for (const element of elements) {
    let originals = originalAttributes.get(element);
    if (!originals) {
      originals = new Map();
      originalAttributes.set(element, originals);
    }
    for (const attribute of attributes) {
      if (!element.hasAttribute(attribute)) continue;
      const current = element.getAttribute(attribute);
      let localized = localizedAttributes.get(element);
      if (!localized) {
        localized = new Map();
        localizedAttributes.set(element, localized);
      }
      if (!originals.has(attribute) || (localized.has(attribute) && current !== localized.get(attribute))) originals.set(attribute, current);
      const original = originals.get(attribute);
      const translated = localizeText(original, lang);
      localized.set(attribute, translated);
      if (element.getAttribute(attribute) !== translated) element.setAttribute(attribute, translated);
    }
  }
}

export function observeUiLocale(root, lang) {
  if (!root) return () => {};
  document.documentElement.lang = lang === 'hi-Latn' ? 'hi-Latn' : lang;
  applyUiLocale(root, lang);
  const observer = new MutationObserver(records => {
    for (const record of records) {
      if (record.type === 'characterData') {
        const node = record.target;
        if (localizedText.has(node) && node.nodeValue === localizedText.get(node)) continue;
        originalText.set(node, node.nodeValue);
        const translated = localizeText(originalText.get(node), lang);
        localizedText.set(node, translated);
        if (node.nodeValue !== translated) node.nodeValue = translated;
      } else if (record.type === 'attributes') {
        const element = record.target;
        const attribute = record.attributeName;
        let localized = localizedAttributes.get(element);
        if (!localized) {
          localized = new Map();
          localizedAttributes.set(element, localized);
        }
        if (localized.has(attribute) && element.getAttribute(attribute) === localized.get(attribute)) continue;
        let originals = originalAttributes.get(element);
        if (!originals) {
          originals = new Map();
          originalAttributes.set(element, originals);
        }
        originals.set(attribute, element.getAttribute(attribute));
        const translated = localizeText(originals.get(attribute), lang);
        localized.set(attribute, translated);
        if (element.getAttribute(attribute) !== translated) element.setAttribute(attribute, translated);
      } else {
        for (const added of record.addedNodes) {
          if (added.nodeType === Node.TEXT_NODE) {
            originalText.set(added, added.nodeValue);
            const translated = localizeText(added.nodeValue, lang);
            localizedText.set(added, translated);
            if (added.nodeValue !== translated) added.nodeValue = translated;
          } else if (added.nodeType === Node.ELEMENT_NODE) {
            applyUiLocale(added, lang);
          }
        }
      }
    }
  });
  observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['title', 'aria-label', 'placeholder', 'alt'] });
  return () => observer.disconnect();
}

